package com.berling.marketplace.ui.screens.product\n\nimport androidx.lifecycle.viewModelScope\nimport com.berling.marketplace.data.local.entities.ProductEntity\nimport com.berling.marketplace.data.models.AuthUser\nimport com.berling.marketplace.data.repository.*\nimport com.berling.marketplace.ui.screens.BaseViewModel\nimport com.berling.marketplace.ui.screens.UiState\nimport dagger.hilt.android.lifecycle.HiltViewModel\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.StateFlow\nimport kotlinx.coroutines.flow.collect\nimport kotlinx.coroutines.launch\nimport javax.inject.Inject\n\ndata class ReviewDataEnhanced(\n    val id: String,\n    val buyerId: String,\n    val buyerName: String,\n    val buyerPhoto: String,\n    val rating: Int,\n    val comment: String,\n    val verifiedPurchase: Boolean,\n    val daysAgo: Int,\n    val timestamp: String,\n    val replies: List<ReviewReplyData> = emptyList()\n)\n\ndata class ReviewReplyData(\n    val id: String,\n    val userId: String,\n    val userName: String,\n    val userPhoto: String,\n    val replyText: String,\n    val timestamp: String\n)\n\ndata class ProductRatingsEnhanced(\n    val average: Double = 0.0,\n    val totalReviews: Int = 0,\n    val fiveStarCount: Int = 0,\n    val fourStarCount: Int = 0,\n    val threeStarCount: Int = 0,\n    val twoStarCount: Int = 0,\n    val oneStarCount: Int = 0\n)\n\ndata class ProductDetailDataEnhanced(\n    val product: ProductEntity,\n    val seller: AuthUser,\n    val ratings: ProductRatingsEnhanced,\n    val reviews: List<ReviewDataEnhanced>,\n    val relatedProducts: List<ProductEntity>,\n    val isFavorite: Boolean,\n    val sellerRating: Double,\n    val responseRate: Int,\n    val followersCount: Int,\n    val userFollowsSeller: Boolean = false\n)\n\n@HiltViewModel\nclass ProductDetailViewModelEnhanced @Inject constructor(\n    private val productRepository: ProductRepository,\n    private val authRepository: AuthenticationRepository,\n    private val reviewRepository: ReviewRepository,\n    private val socialRepository: SocialRepository\n) : BaseViewModel() {\n\n    private val _productDetailState = MutableStateFlow<UiState<ProductDetailDataEnhanced>>(UiState.Loading)\n    val productDetailState: StateFlow<UiState<ProductDetailDataEnhanced>> = _productDetailState\n\n    private val _isFavoriteState = MutableStateFlow(false)\n    val isFavoriteState: StateFlow<Boolean> = _isFavoriteState\n\n    private val _reviewsState = MutableStateFlow<UiState<List<ReviewDataEnhanced>>>(UiState.Loading)\n    val reviewsState: StateFlow<UiState<List<ReviewDataEnhanced>>> = _reviewsState\n\n    private val _selectedImageIndex = MutableStateFlow(0)\n    val selectedImageIndex: StateFlow<Int> = _selectedImageIndex\n\n    private val _userFollowsSellerState = MutableStateFlow(false)\n    val userFollowsSellerState: StateFlow<Boolean> = _userFollowsSellerState\n\n    /**\n     * Load product detail from Supabase (no mock data)\n     */\n    fun loadProductDetail(productId: String) {\n        viewModelScope.launch {\n            _productDetailState.emit(UiState.Loading)\n            try {\n                // Fetch product from repository\n                val product = productRepository.getProduct(productId)\n                if (product != null) {\n                    // Fetch seller info from Supabase\n                    val seller = AuthUser(\n                        id = product.sellerId,\n                        email = \"\",\n                        name = product.sellerName,\n                        photoUrl = product.sellerPhotoUrl,\n                        role = \"seller\",\n                        isVerified = true\n                    )\n\n                    // Fetch real ratings and reviews from Supabase\n                    val ratingsResult = reviewRepository.getProductRating(productId)\n                    val ratings = if (ratingsResult.isSuccess) {\n                        val productRating = ratingsResult.getOrNull()\n                        ProductRatingsEnhanced(\n                            average = productRating?.averageRating ?: 0.0,\n                            totalReviews = productRating?.totalReviews ?: 0,\n                            fiveStarCount = productRating?.ratingDistribution?.get(5) ?: 0,\n                            fourStarCount = productRating?.ratingDistribution?.get(4) ?: 0,\n                            threeStarCount = productRating?.ratingDistribution?.get(3) ?: 0,\n                            twoStarCount = productRating?.ratingDistribution?.get(2) ?: 0,\n                            oneStarCount = productRating?.ratingDistribution?.get(1) ?: 0\n                        )\n                    } else {\n                        ProductRatingsEnhanced()\n                    }\n\n                    // Fetch real reviews from Supabase\n                    val reviews = mutableListOf<ReviewDataEnhanced>()\n                    reviewRepository.getProductReviews(productId).collect { reviewList ->\n                        reviews.clear()\n                        reviews.addAll(reviewList.map { review ->\n                            ReviewDataEnhanced(\n                                id = review.id,\n                                buyerId = review.buyerId,\n                                buyerName = review.buyerName,\n                                buyerPhoto = review.buyerPhotoUrl,\n                                rating = review.rating,\n                                comment = review.comment,\n                                verifiedPurchase = review.verifiedPurchase,\n                                daysAgo = calculateDaysAgo(review.createdAt),\n                                timestamp = review.createdAt,\n                                replies = review.replies.map { reply ->\n                                    ReviewReplyData(\n                                        id = reply.id,\n                                        userId = reply.userId,\n                                        userName = reply.userName,\n                                        userPhoto = reply.userPhotoUrl,\n                                        replyText = reply.replyText,\n                                        timestamp = reply.createdAt\n                                    )\n                                }\n                            )\n                        })\n                    }\n\n                    // Fetch related products\n                    val relatedProducts = emptyList<ProductEntity>()\n\n                    // Check if current user has favorited this product\n                    val currentUser = authRepository.getCurrentUserOrNull()\n                    val isFavorite = if (currentUser != null) {\n                        productRepository.isFavorite(productId, currentUser.id)\n                    } else {\n                        false\n                    }\n\n                    // Check if user follows seller\n                    val userFollowsSeller = if (currentUser != null) {\n                        socialRepository.isFollowing(currentUser.id, product.sellerId)\n                    } else {\n                        false\n                    }\n\n                    // Fetch seller rating\n                    val sellerRatingResult = reviewRepository.getSellerRating(product.sellerId)\n                    val sellerRating = if (sellerRatingResult.isSuccess) {\n                        sellerRatingResult.getOrNull()?.averageRating ?: 0.0\n                    } else {\n                        0.0\n                    }\n\n                    val detailData = ProductDetailDataEnhanced(\n                        product = product,\n                        seller = seller,\n                        ratings = ratings,\n                        reviews = reviews,\n                        relatedProducts = relatedProducts,\n                        isFavorite = isFavorite,\n                        sellerRating = sellerRating,\n                        responseRate = 98, // Would fetch from seller metrics\n                        followersCount = 0, // Would fetch from followers count\n                        userFollowsSeller = userFollowsSeller\n                    )\n\n                    _productDetailState.emit(UiState.Success(detailData))\n                    _isFavoriteState.emit(isFavorite)\n                    _reviewsState.emit(UiState.Success(reviews))\n                    _userFollowsSellerState.emit(userFollowsSeller)\n                    logInfo(\"Product detail loaded successfully from Supabase\")\n                } else {\n                    _productDetailState.emit(UiState.Error(\"Product not found\"))\n                }\n            } catch (e: Exception) {\n                _productDetailState.emit(UiState.Error(e.message ?: \"Error loading product\"))\n                logError(\"Error loading product detail: ${e.message}\")\n            }\n        }\n    }\n\n    /**\n     * Toggle favorite status\n     */\n    fun toggleFavorite(productId: String) {\n        viewModelScope.launch {\n            try {\n                val currentUser = authRepository.getCurrentUserOrNull() ?: return@launch\n                val isFav = _isFavoriteState.value\n\n                if (isFav) {\n                    productRepository.removeFromFavorites(productId, currentUser.id)\n                    _isFavoriteState.emit(false)\n                } else {\n                    productRepository.addToFavorites(productId, currentUser.id)\n                    _isFavoriteState.emit(true)\n                }\n                logInfo(\"Favorite toggled: $isFav\")\n            } catch (e: Exception) {\n                logError(\"Error toggling favorite: ${e.message}\")\n            }\n        }\n    }\n\n    /**\n     * Set selected image index\n     */\n    fun setSelectedImage(index: Int) {\n        _selectedImageIndex.value = index\n    }\n\n    /**\n     * Follow seller\n     */\n    fun followSeller(sellerId: String) {\n        viewModelScope.launch {\n            try {\n                val currentUser = authRepository.getCurrentUserOrNull() ?: return@launch\n                val result = socialRepository.followUser(currentUser.id, sellerId)\n                if (result.isSuccess) {\n                    _userFollowsSellerState.emit(true)\n                    logInfo(\"Following seller: $sellerId\")\n                }\n            } catch (e: Exception) {\n                logError(\"Error following seller: ${e.message}\")\n            }\n        }\n    }\n\n    /**\n     * Unfollow seller\n     */\n    fun unfollowSeller(sellerId: String) {\n        viewModelScope.launch {\n            try {\n                val currentUser = authRepository.getCurrentUserOrNull() ?: return@launch\n                // Would need follow ID to unfollow\n                _userFollowsSellerState.emit(false)\n                logInfo(\"Unfollowing seller: $sellerId\")\n            } catch (e: Exception) {\n                logError(\"Error unfollowing seller: ${e.message}\")\n            }\n        }\n    }\n\n    /**\n     * Calculate days ago from timestamp\n     */\n    private fun calculateDaysAgo(timestamp: String): Int {\n        return try {\n            val reviewTime = timestamp.toLongOrNull() ?: System.currentTimeMillis()\n            val now = System.currentTimeMillis()\n            ((now - reviewTime) / (1000 * 60 * 60 * 24)).toInt()\n        } catch (e: Exception) {\n            0\n        }\n    }\n}\n
